b:if.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:        Custom Theme
Version:     1.1.9.V
----------------------------------------------- */

* {
margin: 0;
padding: 0;
box-sizing: border-box;
}
html{
scroll-behavior: smooth;
background: linear-gradient(45deg,rgba(255, 255, 255, 1) 0%, rgba(255, 255, 255, 1) 86%, rgba(255, 182, 193, 1) 100%);
}
body {
font-family: 'poppins', sans-serif;
}

/* Intro text section */
.intro-text {
  text-align: center;
  max-width: 900px;
  margin: 40px auto 20px auto;
  padding: 0 20px;
}
.intro-text h2 {
  font-size: 33px;
  font-weight: bold;
  margin-bottom: 10px;
  color: #222;
}
.intro-text p {
  font-size: 16px;
  color: #555;
  line-height: 1.6;
}

/* Tools Grid section */



.pdf-tools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 24px;
  padding: 40px 20px;
  max-width: 100%;
  margin: auto;
}

.tool-box {
  border: 1px solid #d1c3c3;
  background: #fff;
  border-radius: 12px;
  padding: 24px;
  text-align: left;
  text-decoration: none;
  color: #111;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.05);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  display: flex;
  flex-direction: column;
  justify-content: start;
  min-height: 240px;
}

.tool-box:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.08);
}

.tool-box img {
  width: 40px;
  height: 40px;
  margin-bottom: 16px;
}

.tool-box h3 {
  font-size: 18px;
  margin-bottom: 10px;
  color: #222;
}

.tool-box p {
  font-size: 14px;
  color: #666;
  line-height: 1.6;
}

/* PDF Filters Styles */
.pdf-filters {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
  margin: 30px auto;
  padding: 0 20px;
  max-width: 900px;
}

.filter-btn {
  padding: 10px 20px;
  border-radius: 20px;
  border: 1px solid #e0e0e0;
  background: #f8f8f8;
  color: #555;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.3s ease;
}

.filter-btn:hover {
  background: #e0e0e0;
}

.filter-btn.active {
  background: #009688;
  color: white;
  border-color: #009688;
}

/* For the filter buttons version */
.filter-btn {
  font-weight: bold;
}

/* OR if you're using plain text filters */
.pdf-filters {
  font-weight: bold;
}

/* Tool search box */
.pdf-tool-search-wrap {
  max-width: 480px;
  margin: 0 auto 10px auto;
  padding: 0 20px;
  position: relative;
}
.pdf-tool-search {
  width: 100%;
  padding: 12px 44px 12px 18px;
  border-radius: 24px;
  border: 1px solid #e0e0e0;
  background: #f8f8f8;
  color: #333;
  font-size: 15px;
  outline: none;
  transition: all 0.3s ease;
}
.pdf-tool-search:focus {
  border-color: #009688;
  background: #fff;
  box-shadow: 0 0 0 3px rgba(0,150,136,0.12);
}
.pdf-tool-search-wrap::after {
  content: "\f002";
  font-family: FontAwesome;
  position: absolute;
  right: 38px;
  top: 50%;
  transform: translateY(-50%);
  color: #999;
  pointer-events: none;
}
.pdf-tool-no-results {
  display: none;
  text-align: center;
  color: #777;
  font-size: 15px;
  padding: 30px 20px;
}
.pdf-tool-no-results.show {
  display: block;
}
.tool-box-hidden {
  display: none !important;
}



.tool-box p {
  font-size: 14px;
  color: #333;
  background: linear-gradient(135deg, #e0faf6, #c7efe9);
  padding: 10px 12px;
  border-radius: 10px;
  margin-top: 10px;
  font-weight: 500;
  line-height: 1.6;
  border-left: 4px solid #009688;
  box-shadow: 0 3px 10px rgba(0,0,0,0.05);
  transition: 0.3s ease;
}
.tool-box:hover p {
  background: linear-gradient(135deg, #d2f7f0, #bdf0e6);
  border-left-color: #00bfa5;
}


/* Title highlight underline */
.tool-box h3 {
  position: relative;
  display: inline-block;
  padding-bottom: 4px;
}
.tool-box h3::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 6px;
  background: #ffcc80;
  border-radius: 4px;
  z-index: -1;
}

/* =================================================================
   PDF TOOL CATEGORY SECTIONS (Blogger Layout-editable Link List widgets)
   Each category below (Organize PDF, Convert PDF, etc.) is its own
   Link List widget, edited from Blogger Dashboard > Theme > Customize
   > Layout -- these styles just turn the plain link list into cards.
   ================================================================= */
.pdf-tool-category {
  max-width: 1200px;
  margin: 0 auto;
  padding: 10px 20px 0 20px;
}
.pdf-cat-title {
  font-size: 20px;
  font-weight: 700;
  color: #222;
  margin: 30px 0 16px 0;
  padding-left: 4px;
  border-left: 4px solid #009688;
  padding-left: 10px;
}
.pdf-tools-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
  list-style: none;
  margin: 0 0 10px 0;
  padding: 0;
}
.pdf-tools-list li {
  margin: 0;
  padding: 0;
  list-style: none;
}
.pdf-tools-list li a.tool-box {
  border: 1px solid #d1c3c3;
  background: #fff;
  border-radius: 12px;
  padding: 20px;
  text-align: left;
  text-decoration: none;
  color: #111;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.05);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 70px;
}
.pdf-tools-list li a.tool-box:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.08);
}
.pdf-tools-list .tool-icon {
  flex: 0 0 auto;
  font-size: 22px;
  color: #009688;
  background: #e0faf6;
  width: 40px;
  height: 40px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.pdf-tools-list li a.tool-box h3 {
  font-size: 16px;
  margin: 0;
  color: #222;
  padding-bottom: 0;
}
.pdf-tools-list li a.tool-box h3::after {
  display: none;
}

/* =================================================================
   GENERAL TOOLS DIRECTORY (Encoding & Decoding, Data Conversion,
   Generators, Website & SEO, AI Generators, Trending Tools, etc.)
   ================================================================= */
.tool-dir-section {
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px 20px 0 20px;
}
.tool-dir-title {
  font-size: 20px;
  font-weight: 700;
  color: #222;
  margin: 30px 0 16px 0;
  display: flex;
  align-items: center;
  gap: 10px;
}
.tool-dir-title .fa {
  color: #009688;
  font-size: 18px;
}
.tool-dir-title .tool-dir-arrow {
  color: #009688;
  font-weight: 400;
  font-size: 16px;
}
.tool-dir-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 20px;
  margin-bottom: 10px;
}
.tool-dir-card {
  border: 1px solid #e0e0e0;
  background: #fff;
  border-radius: 12px;
  padding: 18px;
  text-align: left;
  text-decoration: none;
  color: #111;
  display: block;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.tool-dir-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.08);
}
.tool-dir-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 8px;
  background: #e0faf6;
  color: #009688;
  font-size: 16px;
  margin-bottom: 10px;
}
.tool-dir-card h3 {
  font-size: 16px;
  margin: 0 0 6px 0;
  color: #222;
}
.tool-dir-card p {
  font-size: 13px;
  color: #666;
  line-height: 1.5;
  margin: 0 0 10px 0;
}
.tool-dir-card .tool-dir-open {
  font-size: 13px;
  font-weight: 600;
  color: #009688;
}
/* Hide default "Search This Blog" box and "Powered by Blogger / Report Abuse" attribution */
.BlogSearch,
.Attribution,
#BlogSearch1,
.widget.BlogSearch,
.widget.Attribution {
  display: none !important;
}

