(function($) { 
  $(function() { 
    $('#menu1 li a:not(:only-child)').click(function(e) {
      $(this).siblings('#sub-menu').toggle();
      $('.dropdown').not($(this).siblings()).hide();
      e.stopPropagation();
    });
    $('html').click(function() {
      $('#sub-menu').hide();
    });
  }); 
})(jQuery);


$(".header-main").attr('style', 'visibility: visible;');

document.addEventListener('DOMContentLoaded', function() {
  // Two kinds of Blogger sections are filterable from the pills above:
  //   1. .pdf-tool-category sections, id="pdf-cat-{filter}" (Link List
  //      widgets, cards are <li><a class="tool-box">).
  //   2. .tool-dir-category sections, id="tools-cat-{filter}" (HTML widgets
  //      -- Encoding & Decoding, Torrent & Hashing, Data Conversion
  //      & Formatting, Generators, Website & SEO, Ai Generators,
  //      Trending Tools -- cards are <a class="tool-dir-card">).
  // To add a new filterable category from Blogger Layout, give the new
  // section a class of either "pdf-tool-category" or "tool-dir-category"
  // and an id of "pdf-cat-{filter}" / "tools-cat-{filter}" that matches a
  // data-filter value on a new pill button. The search box filters
  // individual tool cards by name across whichever category (or all of
  // them) is currently selected.
  const filterButtons = document.querySelectorAll('.filter-btn');
  const categorySections = document.querySelectorAll('.pdf-tool-category, .tool-dir-category');
  const searchInput = document.getElementById('pdf-tool-search');
  const noResultsMsg = document.getElementById('pdf-tool-no-results');
  let activeFilter = 'all';

  function sectionMatchesFilter(section, filter) {
    if (filter === 'all') { return true; }
    return section.id === 'pdf-cat-' + filter || section.id === 'tools-cat-' + filter;
  }

  function applyFilters() {
    const query = searchInput ? searchInput.value.trim().toLowerCase() : '';
    let anyVisible = false;

    categorySections.forEach(section => {
      const categoryMatches = sectionMatchesFilter(section, activeFilter);
      const cards = section.querySelectorAll('li, a.tool-dir-card');
      let sectionHasVisibleCard = false;

      cards.forEach(card => {
        const nameEl = card.querySelector('h3');
        const name = nameEl ? nameEl.textContent.trim().toLowerCase() : '';
        const textMatches = query === '' || name.indexOf(query) !== -1;

        if (textMatches) {
          card.classList.remove('tool-box-hidden');
          sectionHasVisibleCard = true;
        } else {
          card.classList.add('tool-box-hidden');
        }
      });

      // While searching, show any category that has a match, regardless of
      // the active pill, so results aren't hidden behind the wrong filter.
      const shouldShowSection = query !== '' ? sectionHasVisibleCard : categoryMatches;
      section.style.display = shouldShowSection ? '' : 'none';

      if (shouldShowSection) {
        anyVisible = true;
      }
    });

    if (noResultsMsg) {
      noResultsMsg.classList.toggle('show', !anyVisible);
    }
  }

  filterButtons.forEach(button => {
    button.addEventListener('click', function() {
      filterButtons.forEach(btn => btn.classList.remove('active'));
      this.classList.add('active');
      activeFilter = this.getAttribute('data-filter');
      applyFilters();
    });
  });

  if (searchInput) {
    searchInput.addEventListener('input', applyFilters);
  }

  applyFilters();
});
